package api

const dashboardTemplates = `
{{define "inicio"}}{{template "topo" .}}
<div class="dashboard">
<div class="dash-cab">
<div><p class="dash-eyebrow">Centro de operações</p><h1>Visão geral do ambiente</h1><p class="muted">Priorize riscos, acompanhe a operação e decida onde agir primeiro.</p></div>
<div class="dash-atualizacao"><span class="muted">Consultado em {{.AsOf}}</span><a class="btn" href="/painel/">Atualizar visão</a></div>
</div>
<details class="dash-personalizar"><summary>Personalizar gráficos</summary><form method="get" action="/painel/"><input type="hidden" name="personalizar" value="1"><fieldset><legend>Escolha o que mostrar na sua página inicial</legend><div class="dash-opcoes">{{range .Options}}<label><input type="checkbox" name="bloco" value="{{.Key}}"{{if .Enabled}} checked{{end}}> {{.Label}}</label>{{end}}</div></fieldset><div class="dash-config-acoes"><button type="submit">Salvar seleção</button><a class="btn" href="/painel/?personalizar=restaurar">Restaurar todos</a></div></form></details>
{{if .EmptySelection}}<p class="aviso atencao">Todos os gráficos estão ocultos. Abra <strong>Personalizar gráficos</strong> para escolher os que deseja acompanhar.</p>{{end}}
{{if .Issues}}<div class="aviso atencao" role="status"><strong>Há dados que precisam de atenção</strong><ul>{{range .Issues}}<li>{{.}}</li>{{end}}</ul><span>Os indicadores indisponíveis aparecem como —, sem assumir valor zero.</span></div>{{end}}
{{if and .InventoryOn (eq .Total 0)}}<div class="aviso atencao"><strong>Nenhum equipamento ativo cadastrado.</strong> Registre um agente e aguarde o primeiro inventário.{{if .Admin}} <a href="/painel/configuracao?aba=agente">Preparar o primeiro agente</a>.{{end}}</div>{{end}}
{{if .Show.indicadores}}<ul class="kpis dash-kpis" aria-label="Indicadores para decisão">{{range .KPIs}}<li><a class="kpi" href="{{.Href}}"><span class="kpi-rot">{{.Label}}</span><span class="kpi-val {{.Color}}">{{.Value}}</span><span class="kpi-sub">{{.Sub}}</span></a></li>{{end}}</ul>{{end}}
<div class="dash-grade">
{{if .Show.conformidade}}<section class="dash-conformidade" aria-labelledby="dash-conformidade"><div class="card-cab"><h2 id="dash-conformidade">Conformidade da frota</h2><a href="/painel/frota">Ver frota →</a></div>
{{if .ComplianceOn}}{{if .FleetTotal}}<p class="dash-numero"><strong>{{.OK}}</strong> de {{.FleetTotal}} equipamentos em dia</p>
<ul class="dash-barras">{{range .States}}<li><a href="{{.Href}}"><span>{{.Label}}</span><strong>{{.N}} <small>{{.Pct}}%</small></strong></a><div class="dash-trilho" aria-hidden="true"><span class="{{.Color}} w{{.Pct}}"></span></div></li>{{end}}</ul>
<p class="dash-nota">Avaliado em {{.EvaluatedAt}}. Estados exclusivos: dado antigo ou desconhecido não significa equipamento conforme.</p>
{{else}}<p class="muted">Sem equipamentos avaliados. A taxa de conformidade fica indisponível até existir uma avaliação.</p>{{end}}
{{else}}<p class="muted">Conformidade indisponível. Os outros indicadores continuam disponíveis conforme suas fontes.</p>{{end}}</section>{{end}}

{{if .Show.decisoes}}<section aria-labelledby="dash-decisoes"><div class="card-cab"><h2 id="dash-decisoes">Decisões e acompanhamentos</h2><a href="/painel/patch?aba=geral">Analisar patches →</a></div>
{{if .Signals}}<ul class="dash-sinais">{{range .Signals}}<li><a href="{{.Href}}"><strong class="dash-contagem {{.Color}}">{{.N}}</strong><span><b>{{.Label}}</b><small>{{.Detail}}</small></span><span aria-hidden="true">→</span></a></li>{{end}}</ul>
{{else}}{{if .Issues}}<p class="muted">Nenhum acompanhamento adicional retornou nas consultas disponíveis. Resolva os avisos antes de concluir que não há pendências.</p>{{else}}<p class="muted">Nenhum acompanhamento adicional nas fontes consultadas. Confira a conformidade e os equipamentos prioritários abaixo.</p>{{end}}{{end}}</section>{{end}}

{{if .Show.sistemas}}<section aria-labelledby="dash-sistemas"><div class="card-cab"><h2 id="dash-sistemas">Composição do ambiente</h2><a href="/painel/inventario">Inventário →</a></div>
{{if .InventoryOn}}{{if .Systems}}<ul class="dash-barras">{{range .Systems}}<li><div class="dash-barra-rot"><span>{{.Label}}</span><strong>{{.N}} <small>{{.Pct}}%</small></strong></div><div class="dash-trilho" aria-hidden="true"><span class="sistema w{{.Pct}}"></span></div></li>{{end}}</ul><p class="dash-nota">Equipamentos ativos agrupados pela família informada no inventário.</p>{{else}}<p class="muted">O perfil dos sistemas aparecerá após o primeiro inventário.</p>{{end}}{{else}}<p class="muted">Inventário indisponível nesta consulta.</p>{{end}}</section>{{end}}

{{if .Show.execucoes}}<section aria-labelledby="dash-execucao"><div class="card-cab"><h2 id="dash-execucao">Execuções · últimos 7 dias</h2><a href="/painel/jobs">Ver jobs →</a></div>
{{if .JobsOn}}{{if .JobTotal}}<p class="dash-numero"><strong>{{.JobTotal}}</strong> jobs criados no período</p><ul class="dash-barras">{{range .Execution}}{{if .N}}<li><div class="dash-barra-rot"><span>{{.Label}}</span><strong>{{.N}} <small>{{.Pct}}%</small></strong></div><div class="dash-trilho" aria-hidden="true"><span class="{{.Color}} w{{.Pct}}"></span></div></li>{{end}}{{end}}</ul><p class="dash-nota">Estado atual dos jobs criados nos últimos 7 dias. Conclusão de um job não comprova, sozinha, conformidade do equipamento.</p>{{else}}<p class="muted">Nenhum job criado nos últimos 7 dias.</p>{{end}}{{else}}<p class="muted">Dados de execução indisponíveis nesta consulta.</p>{{end}}</section>{{end}}

{{if .Show.seguranca}}<section aria-labelledby="dash-seguranca"><div class="card-cab"><h2 id="dash-seguranca">Segurança e correções pendentes</h2><a href="/painel/patch">Investigar correções →</a></div>{{if and .ComplianceOn .FleetTotal}}{{template "dashboard-barras" .Security}}<p class="dash-nota">Percentuais sobre os {{.FleetTotal}} equipamentos avaliados. Um equipamento pode aparecer em mais de uma linha. Pendências podem vir de dados antigos; confira o estado na frota.</p>{{else}}<p class="muted">Sem avaliação disponível para apresentar os riscos.</p>{{end}}</section>{{end}}
{{if .Show.comunicacao}}<section aria-labelledby="dash-comunicacao"><div class="card-cab"><h2 id="dash-comunicacao">Comunicação dos equipamentos</h2><a href="/painel/inventario">Investigar contato →</a></div>{{if and .InventoryOn .Total}}{{template "dashboard-barras" .Communication}}<p class="dash-nota">Último contato recebido pelo servidor. Ausência de contato recente não comprova que o equipamento esteja desligado.</p>{{else}}<p class="muted">Sem dados de equipamentos ativos para mostrar a comunicação.</p>{{end}}</section>{{end}}
{{if .Show.campanhas}}<section aria-labelledby="dash-campanhas"><div class="card-cab"><h2 id="dash-campanhas">Situação das campanhas</h2><a href="/painel/campanhas">Ver campanhas →</a></div>{{if .CampaignsOn}}{{if .CampaignTotal}}<p class="dash-numero"><strong>{{.CampaignTotal}}</strong> campanhas consultadas</p>{{template "dashboard-barras" .Campaigns}}<p class="dash-nota">Estado atual das até 200 campanhas mais recentes. Campanhas pausadas exigem análise antes de retomar.</p>{{else}}<p class="muted">Nenhuma campanha cadastrada.</p>{{end}}{{else}}<p class="muted">Dados de campanhas indisponíveis nesta consulta.</p>{{end}}</section>{{end}}
</div>

{{if .Show.prioridades}}<section aria-labelledby="dash-prioridades"><div class="card-cab"><h2 id="dash-prioridades">Equipamentos para priorizar</h2><a href="/painel/frota">Abrir lista completa →</a></div>
{{if .ComplianceOn}}{{if .Priorities}}<p class="dash-nota">Primeiro os equipamentos com exploração conhecida, depois o estado de conformidade e o contato mais antigo. Abra o equipamento para conferir as evidências.</p>
<div class="tabela"><table><thead><tr><th scope="col">Equipamento</th><th scope="col">Estado e motivo</th><th scope="col">Pendências</th><th scope="col">Último contato</th></tr></thead><tbody>{{range .Priorities}}<tr><td><a href="{{.Href}}"><strong>{{.Name}}</strong></a>{{if .Exploited}}<span class="dash-risco">{{.Exploited}} com exploração conhecida</span>{{end}}</td><td><span class="estado {{.State}}">{{.Label}}</span>{{if .Reason}}<small class="dash-motivo">{{.Reason}}</small>{{end}}</td><td>{{.Pending}}</td><td>{{.Seen}}</td></tr>{{end}}</tbody></table></div>
{{if .More}}<p class="dash-nota">Mais {{.More}} equipamentos precisam de atenção na lista completa.</p>{{end}}
{{else}}{{if .FleetTotal}}<p class="muted">Nenhum equipamento fora do estado em dia nesta avaliação. Consulte os avisos e a atualização dos dados antes de encerrar a análise.</p>{{else}}<p class="muted">Sem equipamentos avaliados para priorizar.</p>{{end}}{{end}}
{{else}}<p class="muted">A priorização depende da avaliação de conformidade, indisponível nesta consulta.</p>{{end}}</section>{{end}}
<p class="dash-nota">Contato recente: até 2 h; sem dado recente na conformidade: mais de 7 dias. Esses limites têm finalidades diferentes. A página reúne o retrato atual das fontes, sem estimar tendências históricas.</p>
</div>
{{template "fim"}}{{end}}
{{define "dashboard-barras"}}<ul class="dash-barras">{{range .}}<li>{{if .Href}}<a href="{{.Href}}"><span>{{.Label}}</span><strong>{{.N}} <small>{{.Pct}}%</small></strong></a>{{else}}<div class="dash-barra-rot"><span>{{.Label}}</span><strong>{{.N}} <small>{{.Pct}}%</small></strong></div>{{end}}<div class="dash-trilho" aria-hidden="true"><span class="{{.Color}} w{{.Pct}}"></span></div></li>{{end}}</ul>{{end}}
`

const dashboardCSS = `
.dash-personalizar{background:#fff;border:1px solid var(--borda);border-radius:var(--raio);padding:.8rem 1rem;margin:0 0 1.25rem}.dash-personalizar summary{cursor:pointer;font-weight:600;color:var(--azul)}.dash-personalizar fieldset{border:0;padding:1rem 0 .6rem;margin:0}.dash-personalizar legend{font-size:.85rem;padding:.75rem 0 0;color:var(--muted)}.dash-opcoes{display:grid;grid-template-columns:repeat(auto-fit,minmax(15rem,1fr));gap:.75rem}.dash-opcoes label{display:flex;align-items:center;gap:.45rem;font-size:.85rem}.dash-config-acoes{display:flex;gap:.75rem;align-items:center;flex-wrap:wrap;margin-top:.7rem}
.dashboard{max-width:94rem;margin:0 auto}
.dash-cab{display:flex;justify-content:space-between;align-items:flex-start;gap:1.5rem;margin:.15rem 0 1.5rem}
.dash-eyebrow{margin:0 0 .4rem;color:var(--azul);font-size:.72rem;font-weight:700;text-transform:uppercase;letter-spacing:.1em}
.dash-cab h1{font-size:1.7rem;letter-spacing:-.035em;margin:0 0 .5rem}.dash-cab p.muted{margin:0;font-size:.9rem}
.dash-atualizacao{display:flex;align-items:flex-end;flex-direction:column;gap:.6rem;font-size:.78rem;flex-shrink:0}
.dash-kpis{grid-template-columns:repeat(3,minmax(0,1fr))}.dash-kpis .kpi{padding:1.1rem 1.25rem}.dash-kpis .kpi-val{font-size:2.15rem;letter-spacing:-.04em;margin:.4rem 0}.dash-kpis .kpi-sub{line-height:1.5}
.dash-grade{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:0 1.25rem}.dash-grade section{min-width:0}
.dashboard section .card-cab a{font-size:.8rem}.dash-numero{color:var(--muted);font-size:.85rem;margin:.2rem 0 1.2rem}.dash-numero strong{font-size:1.7rem;color:var(--texto);margin-right:.25rem}
.dash-barras{padding:0;margin:0;list-style:none}.dash-barras li{margin:0 0 .95rem}.dash-barras a,.dash-barra-rot{display:flex;justify-content:space-between;align-items:center;gap:.75rem;font-size:.86rem;text-decoration:none;color:var(--texto)}.dash-barras a:hover{text-decoration:underline}.dash-barras strong{font-variant-numeric:tabular-nums;white-space:nowrap}.dash-barras small{font-weight:400;color:var(--muted);margin-left:.5rem}
.dash-trilho{height:.5rem;border-radius:999px;background:#eef0f3;overflow:hidden;margin-top:.4rem}.dash-trilho>span{display:block;height:100%;border:0;border-radius:999px}.dash-trilho .em_dia{background:var(--verde-ok)}.dash-trilho .faltando{background:var(--vermelho)}.dash-trilho .reboot_pendente{background:var(--laranja)}.dash-trilho .sem_dado_recente{background:#788398}.dash-trilho .desconhecido{background:#a0acbf}.dash-trilho .sistema{background:var(--azul)}
.dash-sinais{list-style:none;padding:0;margin:0}.dash-sinais li+li{border-top:1px solid var(--borda)}.dash-sinais a{display:flex;align-items:center;gap:.85rem;padding:.8rem 0;color:var(--texto);text-decoration:none}.dash-sinais a:hover b{text-decoration:underline}.dash-sinais a>span:nth-child(2){flex:1;min-width:0}.dash-sinais b{font-size:.86rem;font-weight:600}.dash-sinais small{display:block;color:var(--muted);font-size:.78rem;line-height:1.5;margin-top:.2rem}.dash-contagem{display:grid;place-items:center;min-width:2.6rem;min-height:2.6rem;padding:.25rem;border-radius:.6rem;font-size:1.1rem;font-variant-numeric:tabular-nums}
.dash-nota{color:var(--muted);font-size:.78rem;line-height:1.6;margin:1rem 0 0}.dashboard .card-cab+.dash-nota{margin:0 0 1rem}.dash-motivo{display:block;max-width:40rem;color:var(--muted);margin-top:.35rem;line-height:1.5}.dash-risco{display:block;color:var(--vermelho);font-size:.76rem;margin-top:.35rem}.dashboard .aviso ul{padding-left:1.2rem;margin:.5rem 0}.dashboard .aviso>span{font-size:.8rem}
@media(max-width:1000px){.dash-cab{flex-direction:column;gap:.8rem}.dash-atualizacao{align-items:center;flex-direction:row;flex-wrap:wrap}.dash-kpis{grid-template-columns:repeat(2,minmax(0,1fr))}}
@media(max-width:700px){.dash-grade{grid-template-columns:1fr}.dash-cab h1{font-size:1.4rem}.dash-kpis{gap:.65rem}.dash-kpis .kpi{padding:.9rem}.dash-kpis .kpi-rot{font-size:.68rem}.dash-kpis .kpi-val{font-size:1.8rem}}
@media(max-width:380px){.dash-kpis{grid-template-columns:1fr}}
`
